// 日本の主要な株主優待実施銘柄のデータ
// 2026-11-11 に全銘柄の優待内容を照合し直した(TDnet適時開示 2026-08〜11 と
// 証券会社の優待情報ページ(楽天証券/ミンカブ提供・Yahoo!ファイナンス)との突き合わせ)
//
// 「✓ 検証済み」/「参考情報」の区分(2026-11-11 定義):
//   sourceType: "ir"     - 企業IR・公式優待ページ・適時開示で内容を確認した → 「✓ 検証済み」
//   sourceType: "broker" - 証券会社の優待ページでの照合のみ             → 「参考情報」
//   sourceType 未設定     - 確認元が記録されていない                         → 「参考情報」
//   表示ラベルと件数は isVerifiedYutai()(= sourceType === "ir")だけで決める。
//   dataQuality は旧来の内部区分で、表示ラベルには使わない。
//
// lastVerified vs priceUpdatedAt:
//   lastVerified    - 優待の「内容」を確認した日(verifiedAt)。sourceType / sourceUrl と対で記録する。
//                      照合していない銘柄の値は書き換えない。
//   priceUpdatedAt  - 株価(approxInvestment/yieldPercent)を自動スクリプトで再取得した日。
//                      価格の新旧を表すだけで、内容が再検証されたことは意味しない。

import type { ExperienceTag } from "@/lib/experience-data";

export type PreferenceTag =
  | "cafe" | "noodles" | "japanese" | "family-restaurant" | "izakaya"
  | "coffee" | "tea" | "alcohol" | "sweets"
  | "business-wear" | "casual-wear" | "luxury-brand" | "sports-wear"
  | "makeup" | "skincare" | "hair-salon"
  | "it-gadget" | "games" | "books" | "art"
  | "anime" | "oshi-katsu" | "streaming"
  | "movie" | "theme-park" | "live-concert"
  | "gym" | "sports-watching" | "yoga" | "sauna" | "running" | "cycling"
  | "domestic-flight" | "overseas-travel" | "train" | "hotel";

type Yutai = {
  id: string;
  code: string;
  name: string;
  brands: string[];
  categories: string[];
  lifestyleTags: string[];
  minShares: number;
  approxInvestment: number;
  annualValue: number;
  yieldPercent: number;
  description: string;
  rightsMonths: number[];
  dataQuality: "verified" | "ai_generated";
  // 優待の「内容」を照合した日(verifiedAt)。照合元は sourceType / sourceUrl に記録する。
  // 価格更新スクリプトはこの値を書き換えない。
  lastVerified: string;
  // 株価(approxInvestment/yieldPercent)を機械的に再取得した日。内容の検証日とは別物。
  priceUpdatedAt?: string;
  preferenceTags?: PreferenceTag[];

  // ---- 取得可能最短日の算出用 ----
  // 継続保有の判定で株主名簿への記録が必要な月。優待そのものの基準日(rightsMonths)とは
  // 別の月でも判定される会社があるため分離している。
  // 例: MTG(7806) は優待の基準日は9月末だけだが、継続保有は3月末・9月末の両方で記録される。
  // 未指定なら rightsMonths と同じ(= 優待の基準日でのみ判定される)とみなす。
  recordMonths?: number[];
  // 継続保有要件を満たすために必要な「連続した名簿記録回数」。
  // 1(未指定時の既定値) = 継続保有要件なし。1回記録されれば対象になる。
  // 例: MTG(7806) の「継続1年以上」は3月末・9月末に連続3回記録 → 3
  requiredConsecutiveRecords?: number;
  // 基準日から優待が実際に手元に届く(ポイントが付与される)までの月数。
  // 未指定なら3ヶ月(一般的な「権利確定の2〜3ヶ月後に到着」を踏まえた既定値)。
  receiptLagMonths?: number;

  // ---- 優待制度の状態 ----
  // 未指定は "active" とみなす。"abolished" は制度が廃止された銘柄。
  // 廃止銘柄は非表示にせず「いつの権利分で終わったか」を事実として表示する。
  status?: "active" | "abolished";
  // 廃止銘柄の最後の権利確定月("YYYY-MM")
  lastRecordDate?: string;
  // 廃止に関する補足表示(優待券の発行時期など)
  abolishedNote?: string;
  // 廃止の種類。"delisted" は会社自体が上場廃止(株式を取得できない)。未指定は優待制度のみの廃止。
  abolishedKind?: "yutai" | "delisted";

  // ---- 継続保有条件 ----
  // 基本の優待そのものに保有期間の要件がある場合の表示用ラベル(例: "1年以上")。
  // 増額条件(長く持つと増える)だけの銘柄には付けない。
  // 名簿記録の判定ルール(recordMonths / requiredConsecutiveRecords)が未入力のときは
  // 初回受取見込みを算出しない(推測で記録回数を置くと誤った時期を表示するため)。
  holdingRequirement?: string;
  // 継続保有の到達時に1回だけ進呈される優待(例: NTT の2年到達時・5年到達時)。
  // 毎年もらえるものではないため annualValue には含めず(= 0)、年換算・利回り・並び替えの対象外にする。
  oneTimeBenefits?: Array<{ afterYears: number; value: number }>;

  // ---- 出典 ----
  // 確認元の種類。"ir" = 企業IR・公式優待ページ・適時開示、"broker" = 証券会社の優待ページ。
  // "ir" の銘柄だけを「✓ 検証済み」として表示・集計する。
  sourceType?: YutaiSourceType;
  // 実際に照合したページのURL。lastVerified が確認日(verifiedAt)にあたる。
  // 未入力の銘柄は詳細ページで検索リンクを代わりに表示する。
  sourceUrl?: string;

  // ---- 体験提案モード用 ----
  // この銘柄の優待で実際に体験できる/割引が効く体験タグ。
  // 1銘柄が複数の体験タグを持つこともある(例: 藤田観光は温泉旅館と水族館の両方)。
  // 「14カテゴリ→体験タグ対応表」の一括付与 + 個別確認した例外リストで付与している
  // (詳細は experience-matching.ts の CATEGORY_TO_EXPERIENCE_TAGS を参照)。
  experienceTags?: ExperienceTag[];
};

export type YutaiStatus = NonNullable<Yutai["status"]>;
export type YutaiSourceType = "ir" | "broker";

