export type { Yutai };

// 最終データ更新日(UI表示用)
export const DATA_LAST_UPDATED = "2026-11-11";

// ── 掲載状態の判定 ────────────────────────────────────────────
// 「収録」と「優待を実施中」を区別する。YUTAI_LIST には商品名検索で「優待なし」と
// 返すためだけに収録している銘柄(annualValue: 0)や、廃止・上場廃止の記録も含まれるため、
// 件数表示や一覧はこの判定を通す。

/** 「✓ 検証済み」かどうか。企業IR・公式優待ページ・適時開示で照合した銘柄だけが該当する */
export function isVerifiedYutai(yutai: Yutai): boolean {
  return yutai.sourceType === "ir";
}

export function isAbolishedYutai(yutai: Yutai): boolean {
  return yutai.status === "abolished";
}

/** 継続保有の到達時に1回だけ受け取れる優待を持つか(年換算の対象外) */
export function hasOneTimeBenefit(yutai: Yutai): boolean {
  return (yutai.oneTimeBenefits?.length ?? 0) > 0;
}

/** 毎年受け取れる優待があり、年間優待価値・利回りを算出できる銘柄 */
export function isAnnualizedYutai(yutai: Yutai): boolean {
  return !isAbolishedYutai(yutai) && yutai.annualValue > 0;
}

/** 現在、何らかの株主優待を実施している銘柄(年換算できるもの + 単発のもの) */
export function hasActiveYutai(yutai: Yutai): boolean {
  return isAnnualizedYutai(yutai) || (!isAbolishedYutai(yutai) && hasOneTimeBenefit(yutai));
}

function countBy(pred: (y: Yutai) => boolean): number {
  return YUTAI_LIST.filter(pred).length;
}

/**
 * 件数の内訳。トップ・/stocks・/about で同じ数字を出すため、ここで一度だけ数える。
 *   total = active + abolished + noYutai
 *   active = annualized + oneTimeOnly
 */
export const DATA_STATS = {
  total: YUTAI_LIST.length,
  active: countBy(hasActiveYutai),
  annualized: countBy(isAnnualizedYutai),
  oneTimeOnly: countBy((y) => hasActiveYutai(y) && !isAnnualizedYutai(y)),
  abolished: countBy(isAbolishedYutai),
  delisted: countBy((y) => isAbolishedYutai(y) && y.abolishedKind === "delisted"),
  noYutai: countBy((y) => !isAbolishedYutai(y) && !hasActiveYutai(y)),
  // 証券会社の優待ページだけで照合した銘柄("broker")は検証済みに数えない
  activeVerified: countBy((y) => hasActiveYutai(y) && isVerifiedYutai(y)),
  activeReference: countBy((y) => hasActiveYutai(y) && !isVerifiedYutai(y)),
  // 参考情報のうち、証券会社の優待ページで照合済みの銘柄
  activeBrokerChecked: countBy((y) => hasActiveYutai(y) && y.sourceType === "broker"),
} as const;
